import React, { useRef, useEffect, useState, Fragment } from 'react';
import { useNavigate } from "react-router-dom";
import shuffle from 'array-shuffle';
import wordList from "../jsons/number.json";
import Confetti from "react-confetti";
import { ToastContainer, toast } from "react-toastify";

function MyGameMidContent() {
  const [cursorStyle, setCursorStyle] = useState('default');
  const [count, setCount] = useState(0);

  let requestId;
  let navigate = useNavigate();
  let canvasRef = useRef(null);
  //checking whether cube is paused or nor
  let [isPaused, setIsPaused] = useState(false);


  let [curr_idx, setCurr_Idx] = useState(0);
  let [currQue, setCurrQue] = useState("");
  let [currAns, setCurrAns] = useState(0);

  let [CorrectCnt, setCorrectCnt] = useState(0);
  let [WrongAttemptCnt, setWrongAttemptCnt] = useState(0);
  
  let [numberList, setNumberList] = useState([]);
  let [digitArray, setDigitArra] = useState([]);
  //const numberList = shuffle(wordList.level1);

  
  //react confetti activation or deactivation
  let [congratulationsMessage, setcongratulationsMessage] = useState(false);
  //coin message
  let [coinMessage, setCoinMessage] = useState(false);
  //help popup open-close
  var [open, setOpen] = useState(false);
  //prefix array
  const prefixArray = ["वि", "अनु", "सु", "अव", "नि", "अप"];
  
  const [canvasDimensions, setCanvasDimensions] = React.useState({
    width: 1160,
    height: 560,
  });
  const circles = [];
  let myindex = 0;
  //const [circles, setCircles] = useState([]);




  const [state, setState] = useState({
    gravity: 1,
    speedX: 0,
    speedY: 0,
    x: canvasDimensions.width / 2,
    y: 0,
    width: 300,
    height: 150,
  });

  const handleMouseEnter = () => {
    setCursorStyle('pointer'); // Change cursor style on mouse enter
  };

  const handleMouseLeave = () => {
    setCursorStyle('default'); // Reset cursor style on mouse leave
  };
  
  useEffect(() => {
    console.log(JSON.stringify(numberList));
    console.log("Digit Array data added");
    if(numberList.length>0)
      {
        numberList.forEach((element,idx) => {
          digitArray.push(element.digit);
          if(idx==0){setCurrQue(element.word);}
        });

      }

  }, [numberList]);
  

  useEffect(() => {
    setNumberList(shuffle(wordList.level1));
    handleResize();
    window.addEventListener("resize", handleResize);
    return () => {
      window.removeEventListener("resize", handleResize);
    };
  }, []);

  useEffect(() => {
    if(CorrectCnt!=0)  
      {
        console.log("correct is selected"+(curr_idx+1));
      //  setCurr_Idx(curr_idx+1);
        /*numberList.forEach((element,idx) => {
          //  .push(element.word);
          if(idx==0)
          {
            setCurrQue(element.word);setCurrAns(element.digit);
          }
        });*/

      }
  
    
  }, [CorrectCnt]);


  useEffect(() => {
    if (open) return;
    if (isPaused) return;

    const canvas = canvasRef.current;
    const context = canvas.getContext("2d");

    const gameLoop = () => {
      clear();
      draw();
      
     // update();
      //drawBubbles();
      requestId = requestAnimationFrame(gameLoop); // Request the next frame
    };

    const clear = () => {
      context.clearRect(0, 0, canvas.width, canvas.height);
    };

  



    const playAudio = (soundsorce) => {
      try {
        if (!soundsorce) {
          throw new Error("No audio source provided.");
        }

        const audioElement = new Audio(soundsorce);
        audioElement.currentTime = 0;
        setTimeout(() => {
          audioElement.play();
        }, 1000);
      } catch (error) {
        // Handle the error gracefully, e.g., log it or display a message to the user.
        console.error("Audio playback error:", error.message);
      }
    };

    

    // Function to generate a random number between min and max
    const randomRange = (min, max) => Math.random() * (max - min) + min;

    // Function to create a circle object
    const createCircle = (number) => {
      return {
        x: randomRange(0, canvas.width),
        y: randomRange(0, canvas.height),
        radius: randomRange(40, 65),
        dx: randomRange(0, 2),
        dy: randomRange(0, 2),
        color: `rgba(${randomRange(0, 255)}, ${randomRange(0, 255)}, ${randomRange(0, 255)}, 0.91)`,
        //color: `hsl(${Math.random() * 360}, 50%, 50%)`,
        destroyed: false, // Flag to track if the bubble is destroyed,
        current_number: number
      };
    };
    console.log("data fill");
      
      /*numberList.forEach((element,idx) => {
        //  .push(element.word);
        console.log("numberList=");
        circles.push(createCircle(element.digit));
        if(idx==0)
        {
          setCurrQue(element.word);setCurrAns(element.digit);
        }
      });*/

      digitArray.forEach((element,idx) => {
        circles.push(createCircle(element));
       
      });
    // Initialize five circles
    for (let i = 0; i < 10; i++) {
      
     // circles.push(createCircle(numberList.level1[i].digit));
    }

    const draw = () => {
      context.clearRect(0, 0, canvas.width, canvas.height);

      circles.forEach(circle => {
        if (!circle.destroyed) {
  
        context.beginPath();
        context.arc(circle.x, circle.y, circle.radius, 0, Math.PI * 2, false);
        context.fillStyle = circle.color;
        context.fill();


        // Add text inside the circle
        context.fillStyle = 'white';
        context.font = 'bold 20px Arial';
        context.textAlign = 'center';
        context.textBaseline = 'middle';
        context.fillText(circle.current_number, circle.x, circle.y);

        circle.x += circle.dx;
        circle.y += circle.dy;

        // Bounce off walls
        if (circle.x + circle.radius > canvas.width || circle.x - circle.radius < 0) {
          circle.dx = -circle.dx;
        }
        if (circle.y + circle.radius > canvas.height || circle.y - circle.radius < 0) {
          circle.dy = -circle.dy;
        }
      }
      });
    };


    const handleClick = (event) => {
      //console.log("MYITC2= "+count);
     // alert(count);
    //  setCount(count => count + 1);
     const canvas = canvasRef.current;
      const rect = canvas.getBoundingClientRect();
      const mouseX = event.clientX - rect.left;
      const mouseY = event.clientY - rect.top;
      
  
      circles.forEach((circle,index) => {
        const distance = Math.sqrt((mouseX - circle.x) ** 2 + (mouseY - circle.y) ** 2);
        if (distance <= circle.radius) {
          //circle.destroyed = true;
          //testfn();
          //console.log('Circle clicked index= '+index + "curr_idx= "+curr_idx);
          //console.log('index= '+index + " currenetnIDX= "+curr_idx);
          
        //  setCurr_Idx(curr_idx=>curr_idx+1);
          myindex = myindex+1;
          console.log('myindex= '+myindex);
          return;
          //setCurr_Idx(curr_idx=>curr_idx+1);
          if(curr_idx==index)
          {

            circle.destroyed = true;
            
           
            
            //setCorrectCnt(CorrectCnt+1);
            testfn();
            
          }
          else{
            setWrongAttemptCnt(WrongAttemptCnt+1);
            testfn();
          }
  
          // Handle circle click here
        }
      });
    };

    

    canvas.addEventListener('click', handleClick);





    
   // canvas.addEventListener("mousemove", handleBubbleHover);

    requestAnimationFrame(gameLoop);

    return () => {
     // canvas.removeEventListener("click", handleBubbleClick);
      //canvas.removeEventListener("mousemove", handleBubbleHover);

      if (requestId) {
        cancelAnimationFrame(requestId); // This will stop the animation loop
      }
    };
  }, [state,  open, canvasDimensions]);

  const handleResize = () => {
    const canvasContainer = canvasRef.current.parentNode;
    const newWidth = canvasContainer.offsetWidth;
    const newHeight = canvasContainer.offsetHeight;
    // console.log("newWidth", newWidth);
    // console.log("newHeight", newHeight);
    setCanvasDimensions((prevDimensions) => ({
      ...prevDimensions,
      width: newWidth,
      height: newHeight,
    }));
  };

  



  


  const testfn = () => 
  {
   // alert("helo");
    setCorrectCnt(CorrectCnt=>(CorrectCnt+1));
    setCurr_Idx(curr_idx=>curr_idx+1);
    //circles.push(100);
    
  }

 


  return (
    <div
      className="d-flex justify-content-center align-items-center canvas-background"
      style={{
        height: "100%",
        width: "100%",
        backgroundColor: 'rgba(255, 255, 255, 0.5)',
        borderRadius: "20px",
        backgroundSize: "cover",
        backgroundRepeat: "no-repeat",
      }}
    >
      <canvas
        ref={canvasRef}
        width={canvasDimensions.width}
        height={canvasDimensions.height}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        style={{
          border: "2px solid #000",
          backgroundColor: "transparent",
          backgroundColor: 'rgba(255, 255, 255, 0.1)',
          backgroundSize: "cover",
          backgroundRepeat: "no-repeat",
          cursor: cursorStyle
        }}
      />
      <button
        style={{
          position: 'absolute',
          bottom: '10px',
          zIndex: '1' // Ensure button is above canvas
        }}
      >
        {currQue}
      </button>

      <button
        style={{
          position: 'absolute',
          top: '10px',
          left:'100px',
          zIndex: '1' // Ensure button is above canvas
        }}
      >
        {myindex}hel
      </button>
      

      {congratulationsMessage ? (
        <Fragment>
          <Confetti numberOfPieces={200} gravity={0.15} />
        </Fragment>
      ) : (
        <Fragment></Fragment>
      )}

      <div className="custom-toast-container">
        <ToastContainer />
      </div>

      {/* {coinMessage && <GoldCoinsEarned />} */}
      {coinMessage}

     
    </div>
  );
};
export default MyGameMidContent;
