
import React from "react";
// import { useNavigate } from "react-router-dom";
// import BackNextBar from "../MajorComponents/BackNextBar";
import "./Mid.css";
import { useTranslation } from "react-i18next";
import ReactPlayer from 'react-player';
import video_file from "../videos/activity_video.webm";
import "./ResponsivePlayer.css"

const AnimationMidContent = () => {
  const { t } = useTranslation();


  return (
    
    <div className="overflow-auto scrollbar-primary rounded" style={{ height: "96%",marginTop:"10px", backgroundColor:"#ffffff"}}>

          
        <div className="player-wrapper">
          <ReactPlayer
            className="react-player"
            url={video_file}
            width="100%"
            height="100%"
            controls={true}
          />
        </div>
         </div>
        
    
  );
};

export default AnimationMidContent;
