// App2.js
import React, { useRef, useEffect, useState } from 'react';

function App2() {
  const canvasRef = useRef(null);
  const [clickCount, setClickCount] = useState(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    let x = canvas.width / 2;
    let y = canvas.height / 2;
    const radius = 50;
    let dx = 2;
    let dy = -2;

    const drawCircle = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.beginPath();
      ctx.arc(x, y, radius, 0, Math.PI * 2);
      ctx.fillStyle = 'red';
      ctx.fill();
      ctx.closePath();
      
      // Display click count inside the circle
      ctx.font = "20px Arial";
      ctx.fillStyle = "white";
      ctx.textAlign = "center";
      ctx.fillText(clickCount.toString(), x, y + 8); // Adjust the position as needed
    };

    const update = () => {
      x += dx;
      y += dy;
      if (x + radius > canvas.width || x - radius < 0) {
        dx = -dx;
      }
      if (y + radius > canvas.height || y - radius < 0) {
        dy = -dy;
      }
    };

    const handleClick = (event) => {
      const rect = canvas.getBoundingClientRect();
      const clickX = event.clientX - rect.left;
      const clickY = event.clientY - rect.top;

      // Calculate distance between click point and circle center
      const distance = Math.sqrt((clickX - x) ** 2 + (clickY - y) ** 2);

      // If distance is less than or equal to radius, the click is inside the circle
      if (distance <= radius) {
        setClickCount(prevCount => prevCount + 1);
      }
    };

    canvas.addEventListener('click', handleClick);

    const animate = () => {
      drawCircle();
      update();
      requestAnimationFrame(animate);
    };

    animate();

    // Cleanup function
    return () => {
      canvas.removeEventListener('click', handleClick);
      cancelAnimationFrame(animate);
    };
  }, [clickCount]); // Add clickCount to the dependency array

  return <canvas ref={canvasRef} width={800} height={600} />;
};


export default App2;
