import React from "react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
} from "@mui/material";
import Slide from '@mui/material/Slide';
import { t } from 'i18next';
import { createTheme, ThemeProvider } from '@mui/material/styles'
import {  pink } from '@mui/material/colors';;

const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="down" ref={ref} {...props} />;
});
const { palette } = createTheme();
const theme = createTheme({
  palette: {
    primary: {
      main: palette.primary.dark,
      contrastText: "#fff" 
    },
    secondary: {
      main: pink[500],
      contrastText: "#fff" 
    },
  },
});
const Hintpopup = ({ openDialog,  closeDialog, content,popuptitle }) => {
  return (
    <>
      <Dialog open={openDialog} TransitionComponent={Transition}>
        <DialogTitle>
          {popuptitle}
        </DialogTitle>
        <DialogContent dividers style={{marginLeft:"0%"}}>
          {content}
        </DialogContent>
        <DialogActions>
        <ThemeProvider theme={theme}>
          <Button variant="contained" color="secondary" size="small" onClick={closeDialog}>
            {t("ok")}
          </Button>
        </ThemeProvider>  
        </DialogActions>
      </Dialog>
    </>
  );
};

export default Hintpopup;
