import React,{useEffect} from "react";
import HelpingToolsMidContent from "../midcomponent/HelpingToolsMidContent.js";
import {NmCommon} from 'olabsnxtg-sanskrit'
import Quizinstructions from "../popups/Quizinstructions.js";
import { useTranslation } from "react-i18next";

import logconfig from '../config/dbconfig.js';
import useWebSocket from 'react-use-websocket';
import {SendLogData} from "../config/wslog.js";
import ReactGA from "react-ga4";
const HelpingTools = () => {

  const { t } = useTranslation();


  const {sendJsonMessage } = useWebSocket(logconfig.logurl, {share: true,});

  useEffect(() => {
    ReactGA.send({ hitType: "pageview", page: logconfig.activityUniqueName+"|"+logconfig.activityName+"|launchpage",
     title: logconfig.activityUniqueName+"|"+logconfig.activityName+"|launchpage" });
   }, []);


  const Theory_Pg_fn = () => {
    SendLogData(
      sendJsonMessage,
      "Menu",
      "Thoery",
      "Clicked",
      "Click on Start Button"
    )
  }

  const Instruction_Pg_fn = () => {
    SendLogData(
      sendJsonMessage,
      "Menu",
      "Instruction",
      "Clicked",
      "Click on Instruction Button"
    )
  }

  const Helping_Pg_fn = () => {
    SendLogData(
      sendJsonMessage,
      "Menu",
      "Start",
      "Helping",
      "Click on Helping Button"
    )
  }

  const QuizOpenPopupFn = () => {
    SendLogData(
      sendJsonMessage,
      "Menu",
      "Quiz",
      "Clicked",
      "Click on Quiz Button"
    )
  }

  const QuizOkfn = () => {
    SendLogData(
      sendJsonMessage,
      "Menu",
      "OK",
      "Clicked",
      "Click on OK Button",
      [],
      [{"popuptype":"Confirmation box","popuptext":"Instructions for quiz."}]
    )
  }

  const QuizCancelFn = () => {
    SendLogData(
      sendJsonMessage,
      "Menu",
      "Cancel",
      "Clicked",
      "Click on Cancel Button",
      [],
      [{"popuptype":"Confirmation box","popuptext":"Instructions for quiz."}]
    )
  }



  const HomeOpenPopupFN = () => {
    SendLogData(
      sendJsonMessage,
      "Menu",
      "Home",
      "Clicked",
      "Click on Home Button"
    )
  }


  const HomeOkFn = () => {
    SendLogData(
      sendJsonMessage,
      "Menu",
      "OK",
      "Clicked",
      "Click on OK Button",
      [],
      [{"popuptype":"Confirmation box","popuptext":"Are you sure you want to quit?"}]
    )
  }

  const HomeCancelFn = () => {
    SendLogData(
      sendJsonMessage,
      "Menu",
      "Cancel",
      "Clicked",
      "Click on Cancel Button",
      [],
      [{"popuptype":"Confirmation box","popuptext":"Are you sure you want to quit?"}]
    )
  }


  return (
    <div>
      <NmCommon
        H_title={t("activity_title")}
        H_sidebarvisible="false"
        HQ_quittext={t("quit_text")}
        HQ_yes={t("start_ok")}
        HQ_cancel={t("start_cancel")}
        RSM_QuizPopupContent_comp=<Quizinstructions/> // here you have to add instructio of quiz (you can make a component and add it here)
        RSM_Intruc_popup_title_string={t("headingquiz_instruct")}
        RSM_ok={t("start_ok")}
        RSM_theory_tt={t("theory")}
        RSM_vivavoce_tt={t("viva_voce")}
        RSM_helpingtool_tt={t("help")}
        TH_midcontent_comp={<HelpingToolsMidContent />} // here you have to add Theory (you can make a component and add it here)
        isTheoryShow={true}
        isInstructionShow={true}
        isQuizShow ={true}
        isHelpingToolShow={true}
        //workbenchlabel="this is workbench lebel"


        Theory_Pg_fn={Theory_Pg_fn}
        Instruction_Pg_fn={Instruction_Pg_fn}
        Helping_Pg_fn={Helping_Pg_fn}

        QuizOpenPopupFn={QuizOpenPopupFn}
        QuizOkfn={QuizOkfn}
        QuizCancelFn={QuizCancelFn}

        HomeOpenPopupFN={HomeOpenPopupFN}
        HomeOkFn={HomeOkFn}
        HomeCancelFn={HomeCancelFn}

        ActivityUniqueName={logconfig.activityUniqueName}
        ActivityName={logconfig.activityName}

        isRSMshow={true}

        LHomeNavigation=""
        SendLogData={SendLogData}
        sendJsonMessage={sendJsonMessage}
        
      />
    </div>
  );
};

export default HelpingTools;
