import React, { useState } from "react";
import {useEffect, useRef} from 'react';
import { useNavigate } from "react-router-dom";
import jsondata from '../jsons/data.json';
import arrayShuffle from 'array-shuffle';
import { DragDropContainer, DropTarget } from 'react-drag-drop-container';
import picture1 from "../Img/picture1.jpg";
import picture2 from "../Img/picture2.jpg"
import picture3 from "../Img/picture3.jpg"
import picture4 from "../Img/picture4.jpg"
import picture5 from "../Img/picture5.jpg"
import info from '../Img/info.png'
import correctbox from "../Img/correctbox.png";
import incorrectbox from "../Img/incorrectbox.png";
import FeedbackPopupContent from "../popups/FeedbackPopupContent";
import Feedbackpopup from "../popups/Feedbackpopup";
import Hintpopup from "../popups/Hintpopup";
import HintPopupContent from "../popups/HintPopupContent";

const ActivityMidContent = ({}) => {

  const navigate = useNavigate();

  let [suffledArr,setSuffledArr] = useState(arrayShuffle([1,2,3,4,5]));
  let [CurrArrIndex,setCurrArrIndex] = useState(0);
  let [CurrentImg,setCurrentImg] = useState();
  let [optionArr,setOptionArr] = useState([]);
  let [sentenceArr,setSentenceArr] = useState([]);
  let [count,setCount] = useState(0);
  let [blankArr,setBlankArr] = useState(Array(8).fill(""));
  let [temp,setTemp] = useState();
  let[myboolean,setMyboolean] = useState(false);
  let [answerArr,setAnswerArr] = useState([]);
  let [isCorrectArr,setIsCorrectArr] = useState([]);//correct incorrect Array
  let [isSubmit,setSubmit] = useState(false);

  let [hintArr,setHintArr] = useState([]);


  const [showDialog, setShowDialog] = useState(false);
  let [myFeedback,setMyFeedback] = useState();

  const [showHint, setShowHint] = useState(false);
  


  const closeDialog = () => {setShowDialog(false);};
  const closeHint = () => {setShowHint(false);};

  const feedback = (parm1) =>
  {
   setMyFeedback("यह स्थान अन्य शब्द का है। कृपया सही शब्द का चयन करें।");
   setShowDialog(true);
  }
  



useEffect(()=>{
  //alert(jsondata.length);
  console.log(JSON.stringify(suffledArr));
},[suffledArr]);


useEffect(()=>{
  //alert(jsondata.length);
//  console.log(JSON.stringify(optionArr));
},[optionArr]);


//useEffect(()=>{
  //alert(jsondata.length);
 // console.log(JSON.stringify(sentenceArr));
//},[sentenceArr]);


useEffect(()=>{
  //alert(jsondata.length);
  console.log("blankArr "+JSON.stringify(blankArr));
},[blankArr]);

useEffect(()=>{
  //alert(jsondata.length);
  console.log("isCorrectArr "+JSON.stringify(isCorrectArr));
},[isCorrectArr]);

const onHint = () =>{
  setShowHint(true);
}

const onNext = () =>{
    if(CurrArrIndex==4)
    {
      navigate("/completed");
    }
    else{
      setSubmit(false);
      setBlankArr(Array(8).fill(""));
      setIsCorrectArr([]);
      setAnswerArr([]);
      setCurrArrIndex(CurrArrIndex+1);
    }
    
}


const onPrev = () =>{
  setSubmit(false);
  setBlankArr(Array(8).fill(""));
  setIsCorrectArr([]);
  setAnswerArr([]);
  setCurrArrIndex(CurrArrIndex-1);
}

const onClear = () =>{
  setSubmit(false);
  
  setIsCorrectArr([]);
  setBlankArr(Array(8).fill(""));
  
}


const shoot = () =>
{

  setSubmit(true);
  console.log("0 "+answerArr[0]+" "+blankArr[0]);
 // console.log("shoot answerArr "+JSON.stringify(answerArr));
  if(answerArr[0]===blankArr[0])
  {
    addToIsCorrectArr(true);
    
  } 
  else 
  {
    addToIsCorrectArr(false);
  }

  if(answerArr[1]===blankArr[1])
  {addToIsCorrectArr(true)} else {addToIsCorrectArr(false)}

  if(answerArr[2]===blankArr[2])
  {
    addToIsCorrectArr(true)
  } else {addToIsCorrectArr(false)}

  if(answerArr[3]===blankArr[3])
  {
    addToIsCorrectArr(true)
  } else {addToIsCorrectArr(false)}

  if(answerArr[4]===blankArr[4])
  {
    addToIsCorrectArr(true)
  } else {addToIsCorrectArr(false)}
}


useEffect(()=>{

  sentenceArr.map((sentenceitem,index1)=>
  {
    {
      sentenceitem.sentenceWordArr.map((words,index2)=>
      {
        if(words.isBlank)
        {
            addToAnswerArr(words.word);
        }
      });
    }  
  }); 


},[sentenceArr]);


const addToAnswerArr =(arrElement) =>{
  setAnswerArr((prev) => [...prev, arrElement]);
}


const addToIsCorrectArr =(arrElement) =>{
  setIsCorrectArr((prev) => [...prev, arrElement]);
}



useEffect(()=>{
  jsondata.map((slot)=>
        {
          if(slot.slot_id==suffledArr[CurrArrIndex]) {

            setCurrentImg(slot.picture_name);
            setOptionArr(arrayShuffle(slot.options));
            setHintArr(slot.hint);
            //setSentenceArr(arrayShuffle(slot.sentenceArr));
            setSentenceArr(slot.sentenceArr);
          }
        })
},[CurrArrIndex]);


const onHitCall = (e,i) => {
  // console.log("name"+e.dragData[0].id);
  // setTemp();
  setSubmit(false);
  setIsCorrectArr([]);

  blankArr.splice(i, 1, e.dragData[0].id);
  if(myboolean){setMyboolean(false) }else setMyboolean(true);
  //setBlankArr(blankArr);


  // if(e.dragData[0].id=="suraj")
  // {
  //   setTemp(e.dragData[0].id);
  // }

}


  
  return (
    <div>
      <br/>
      <div className="row">
        <div className="col-lg-11 col-md-11 col-sm-8">
          <div className="whitebox rounded-2 shadow fw-bold p-1 ti" style={{color:"#412410"}}>
          Instruction: Complete the activity by dragging the appropriate word from the word list to their correct position.
          </div>
        </div>
        <div className="col-lg-1 col-md-1 col-sm-1"><button onClick={onHint} style={{color:"#412410"}} className="rounded-2 shadow border-0 fw-bold ps-3 pe-3 pt-1 pb-1">Hint</button></div>
      </div> 
      {/* row  closed*/}
     
      <div className="row text-center">
        <div className="col-lg-11 col-12  ms-lg-5">
            <div className="row">
                <div className="col-lg-5 col-12 p-1">
                <div className="bg-white shadow rounded-2 mt-2   pt-2 pb-2">
                {
                (CurrentImg=="picture1")?  <img src ={picture1} className="pictureclass"/>:
                (CurrentImg=="picture2")?  <img src ={picture2} className="pictureclass"/>:
                (CurrentImg=="picture3")?  <img src ={picture3} className="pictureclass"/>:
                (CurrentImg=="picture4")?  <img src ={picture4} className="pictureclass"/>:
                (CurrentImg=="picture5")?  <img src ={picture5} className="pictureclass"/>
                :""
                }
                </div>  
                </div>
                <div className="col-lg-7 col-12 bg-white shadow rounded-2 mt-2 p-0">
                {
                sentenceArr.map((sentenceitem,index1)=>
                {
                  return(<div className="sentence1" style={{textAlign:"left",justifyContent:"left"}} key={index1} >
                    {
                      sentenceitem.sentenceWordArr.map((words,index2)=>
                      { 
                        return (
                            <span>
                            {
                              /* not submit blank*/
                              (words.isBlank && !isSubmit) ? 
                                <DropTarget targetKey=""  onHit={e => onHitCall(e,index1)}>
                                  <div className="fillblank">{blankArr[index1]}</div>
                                </DropTarget>:
                                /* correct 1 */(words.isBlank && isSubmit && index1==0 && isCorrectArr[0]) ?   
                                <div className="tblcellcorrect">{blankArr[index1]}</div>:
                                /* correct 2 */(words.isBlank && isSubmit && index1==1 && isCorrectArr[1]) ?   
                                <div className="tblcellcorrect">{blankArr[index1]}</div>:
                                /* correct 3 */(words.isBlank && isSubmit && index1==2 && isCorrectArr[2]) ?   
                                <div className="tblcellcorrect">{blankArr[index1]}</div>:
                                /* correct 4 */(words.isBlank && isSubmit && index1==3 && isCorrectArr[3]) ?   
                                <div className="tblcellcorrect">{blankArr[index1]}</div>:
                                /* correct 5 */(words.isBlank && isSubmit && index1==4 && isCorrectArr[4]) ?   
                                <div className="tblcellcorrect">{blankArr[index1]}</div>:
                                /* incorrect 5 */(words.isBlank && isSubmit && index1==0 && !isCorrectArr[0]) ?   
                                <DropTarget targetKey=""  onHit={e => onHitCall(e,index1)}><div className="tblcellincorrect" style={{marginRight:"10px"}}>{blankArr[index1]}<img src={info} className="imginfo" onClick={()=>feedback('ji')}/></div></DropTarget>:
                                /* incorrect 5 */(words.isBlank && isSubmit && index1==1 && !isCorrectArr[1]) ?   
                                <DropTarget targetKey=""  onHit={e => onHitCall(e,index1)}><div className="tblcellincorrect">{blankArr[index1]}<img src={info} className="imginfo" onClick={()=>feedback('ji')}/></div></DropTarget>:
                                /* incorrect 5 */(words.isBlank && isSubmit && index1==2 && !isCorrectArr[2]) ?   
                                <DropTarget targetKey=""  onHit={e => onHitCall(e,index1)}><div className="tblcellincorrect">{blankArr[index1]}<img src={info} className="imginfo" onClick={()=>feedback('ji')}/></div></DropTarget>:
                                /* incorrect 5 */(words.isBlank && isSubmit && index1==3 && !isCorrectArr[3]) ?   
                                <DropTarget targetKey=""  onHit={e => onHitCall(e,index1)}><div className="tblcellincorrect">{blankArr[index1]}<img src={info} className="imginfo" onClick={()=>feedback('ji')}/></div></DropTarget>:
                                /* incorrect 5 */(words.isBlank && isSubmit && index1==4 && !isCorrectArr[4]) ?   
                                <DropTarget targetKey=""  onHit={e => onHitCall(e,index1)}><div className="tblcellincorrect">{blankArr[index1]}<img src={info} className="imginfo" onClick={()=>feedback('ji')}/></div></DropTarget>:
                                <label className="opt_font_size" style={{marginRight:"3px"}}>{words.word}</label>
                            }
                            </span>
                        )
                      }) 
                    

                    } </div>)
                })
                }
                  </div>
            </div>
        </div>
      </div>    
      {/* row  closed*/}
      <br/>
     
      <div className="row">
        <div className="col-11 col-lg-12  ms-1 me-1">
          <div className="row text-center">
              <div className="col-lg-2"></div>
              <div className="col-7 col-lg-6  bg-white shadow rounded-2 pt-lg-3 pb-lg-2" >
              {
                optionArr.map((option,index1)=>
                  {

                      return(<DragDropContainer targetKey="" dragData={[{ id: option,src:"suraj",name:"suraj"}]}>
                                <button style={{border:"0px",color:"#412410"}} className="opt_font_size fillcolor shadow rounded-2 m-1 ps-lg-3 pe-lg-3 p-1">{option}
                                </button>
                            </DragDropContainer>);
                  })    
              }
              </div>
              <div className="col-4 col-lg-2 bg-white shadow rounded-2 ms-1 pt-lg-3 pb-lg-1">
                <div className="text-start ps-lg-3"><img src={correctbox} height={20}/>&nbsp;<label className="txtinstructionboxcorrect opt_font_size">Correct</label><br/></div>
                <div className="text-start ps-lg-3"><img src={incorrectbox} height={20}/>&nbsp;&nbsp;<label  className="txtinstructionboxincorrect opt_font_size">Incorrect</label><br/></div>
                <div className="text-start ps-lg-3"><img src={info} height={20}/>&nbsp;&nbsp;<label className="txtviewfeedback opt_font_size">Feedback</label></div>
              </div>
              <div className="col-lg-2"></div>
              </div> 
        </div>
        
        
      </div>
      {/* row  open*/}
      <div className="row">
      
      
      
        
      </div>
      {/* row  closed*/}

      {/* row  open*/}
      <br/>
      <div >
      {
      (CurrArrIndex>0) ? <button onClick={onPrev} style={{color:"#f6a700"}} className="bg-white text-center btnall m-1">PREV</button>:""
      }
        
        <button onClick={shoot} className="bg-white text-center btnall m-1" style={{color:"#439803"}}>SUBMIT</button>
        <button onClick={onNext} style={{color:"#f6a700"}} className=" bg-white text-center btnall m-1">NEXT</button>
        <button onClick={onNext} style={{color:"#E65353"}} className=" bg-white text-center btnall m-1">CLEAR</button>
        
      </div>
      {/* row  closed*/}
      <Feedbackpopup
        openDialog={showDialog}
        closeDialog={closeDialog}
        content={<FeedbackPopupContent person={myFeedback}/>}
        popuptitle="प्रतिपुष्टि (Feedback)"
      />
      <Hintpopup
      openDialog={showHint}
      closeDialog={closeHint}
      content={<HintPopupContent hintArr={hintArr}/>}
      popuptitle="Hints "
      />
      
    </div>
  );
};

export default ActivityMidContent;
