/* eslint-disable jsx-a11y/alt-text */

import React from "react";
// import { useNavigate } from "react-router-dom";
// import BackNextBar from "../MajorComponents/BackNextBar";
import "./Mid.css";
import { useTranslation } from "react-i18next";
import fig1 from "../Img/fig1.png";
import info from "../Img/info.png";
import exitImg from "../Img/exit.png";
import helpImg from "../Img/help.png";
const ProcedureMidContent = () => {
  const { t } = useTranslation();


  return (
    <div className="overflow-auto scrollbar-primary" style={{ height: "95%",marginTop:"15px" }}>
      <div className="my-1 proInstructext" style={{ width: "98%" }}>
        
      <label className="theorytexttitle" style={{textAlign:'left', color:"#412410"}}><b>{t("procedure_title")}</b></label>
      <br/>

      <label className="theorysubtitle" style={{color:"#412410"}}><b>{t("procedure_heading1")}</b></label>
      <br/><br/>

     
      <label className="theorytext" style={{color:"#412410"}}><b>{t("procedure_heading2")}</b></label>

      <ol>
        <li className="theorytext"><div dangerouslySetInnerHTML={{__html: t("procedure_point_1")}}/></li>
        <li className="theorytext"><div dangerouslySetInnerHTML={{__html: t("procedure_point_2")}}/></li>
        <li className="theorytext"><div dangerouslySetInnerHTML={{__html: t("procedure_point_3")}}/><br/>
        <div>
              <div className="text-center col-12 col-xxl-6">
                <img src={fig1} className="border border-dark img-class"/>
              </div>
            
            <div className="text-center col-12 col-xxl-6">
              <label className="fw-bold">Fig. 1: उपसर्ग</label>
            </div>
          </div>
        </li>
        <li className="theorytext"><div dangerouslySetInnerHTML={{__html: t("procedure_point_4")}}/></li>
        <li className="theorytext"><div dangerouslySetInnerHTML={{__html: t("procedure_point_5")}}/></li>
        <li className="theorytext"><label dangerouslySetInnerHTML={{__html: t("procedure_point_61")}}/></li>
        <li className="theorytext"> Click on the <img src={helpImg} height={16} /> icon to read the instructions in the middle of the game. </li>
      </ol>

      <b className="theorytext"><div dangerouslySetInnerHTML={{__html: t("procedure_point_10")}}></div></b>
      <br/><br/>
      </div>
    </div>
  );
};

export default ProcedureMidContent;
