import React, { useState } from "react";
import {useEffect, useRef} from 'react';
import Confetti from "react-confetti";
import { useNavigate } from "react-router-dom";

const CompletedMidContent = ({}) => {
  const navigate = useNavigate();

  const onFinish=()=>{
    navigate("/");
  }
  
  return (
    <div>
      <Confetti
        className="canvas"
        numberOfPieces={150}
        gravity={0.15}
      />
      <div className="compeletddiv">
                  <label className="txtcomplete bg-white p-2 shadow rounded-2" style={{marginTop:"15%"}}>बधाई हो ! आपने सभी वाक्य पूरे कर लिए हैं।</label>
                </div>
                <br/><button  onClick={onFinish} className="btnclear">FINISH</button>
      
    </div>
  );
};

export default CompletedMidContent;
